def setup(b,name,w=320):
 c,p,e,pr=f.setup(b,name,w,'multiple');p.evaluate('sharedTest.seed()');p.evaluate('promotionTest.groups()');return c,p,e,pr
def edit(p,id=1):p.evaluate('id=>sharedTest.edit(id)',id);p.wait_for_timeout(850)
def rec(p,id):return p.evaluate('id=>sharedTest.record(id)',id)
def nested(p,button,panel):
 if p.locator(panel).is_hidden():p.locator(button).tap()
def members(p):return [rec(p,id) for id in [1,50,51]]
def intrinsic_editor(b,name,w):
 c,p,e,pr=setup(b,name,w);before=copy.deepcopy(state(p));schedule=compose(p);checks=f.sources(p);order=p.evaluate('sharedTest.order()');edit(p)
 p.locator('#name').fill('Shared pork recipe');section(p,'timing');p.locator('#prep').fill('17');p.locator('#totaltime').fill('90');p.locator('#marinate').fill('1 hour');section(p,'recipe');nested(p,'#toggleIngredients','#ingredientsPanel');p.locator('#ingredients').fill(p.locator('#ingredients').input_value()+'\n1 tbsp new spice');nested(p,'#toggleInstructions','#instructionsPanel');p.locator('#recipeInstructions').fill(p.locator('#recipeInstructions').input_value()+'\n\nRest before serving.');p.locator('#url').fill('https://example.com/shared-recipe')
 section(p,'notes');nested(p,'#toggleRecipeNotes','#recipeNotesPanel');p.locator('#recipeNotes').fill('Shared saved note');p.locator('#editNeedsTweakingNote').fill('Use more herbs');p.locator('#recipeMakeAhead>summary').tap();p.get_by_role('textbox',name='Preparation task',exact=True).fill('Thaw safely')
 section(p,'organization');p.locator('#recipeLabels').tap();d=p.locator('[role=dialog]').last;d.get_by_text('Added',exact=True).locator('..').get_by_role('checkbox').tap();d.get_by_role('button',name='OK',exact=True).tap();p.locator('#save').tap();assert not p.get_by_role('dialog').count() and not p.locator('#editor .editor').count()
 for m in members(p):assert m['name']=='Shared pork recipe' and m['prep']=='17' and m['total']=='90' and m['marinate']=='1 hour' and m['notes']=='Shared saved note' and m['needsTweakingNote']=='Use more herbs' and m['url']=='https://example.com/shared-recipe' and m['makeAheadTasks'][0]['description']=='Thaw safely' and m['labels']==['Root','Added'] and m['ingredients'][-1]=='1 tbsp new spice' and m['instructions'][-1]['text']=='Rest before serving.'
 for id in [1,50,51]:
  m=rec(p,id);old=next(x for x in before['meals'] if x['id']==id)
  for key in ['id','cat','rotation','linkGroup','linkedMealIds','ingredientStepLinks','lastCooked','favorite']:assert m.get(key)==old.get(key),(key,m,old)
 assert rec(p,2)==next(x for x in before['meals'] if x['id']==2);assert p.evaluate('sharedTest.order()')==order and compose(p)==schedule
 assert state(p)['sessions']==before['sessions'] and state(p)['scales']==before['scales'],(before['sessions'],state(p)['sessions'],before['scales'],state(p)['scales']);assert all(s['checked']==checks[id]['checked'] for id,s in f.sources(p).items() if id in checks)
 expected=state(p);backup=p.evaluate('sharedTest.backup()');p.reload();assert state(p)==expected;p.evaluate('sharedTest.favorite(50)');assert all(m['favorite'] for m in members(p));p.evaluate('b=>sharedTest.restore(b)',backup);p.reload();assert state(p)==expected and not e,e
 if pr:assert p.evaluate("localStorage.getItem('mealRotationDataV1')")=='WORKING SENTINEL'
 print('PASS',name,w,'one editor Save synchronizes intrinsic fields by linkGroup without scope prompts; IDs/local memberships/order/links/progress/scales/schedule/groceries retained; no name-based sync; reload/backup',flush=True);c.close()
