 peer_order=[id for id in p.evaluate('sharedTest.order()') if rec(p,id)['cat']=='Mains'];p.evaluate('sharedTest.shift(1)');assert not p.get_by_role('dialog').count();assert [id for id in p.evaluate('sharedTest.order()') if rec(p,id)['cat']=='Mains']==peer_order
 p.evaluate('sharedTest.apply([1],{rotation:false})');assert not rec(p,1)['rotation'] and rec(p,50)['rotation'] is False and rec(p,51)['rotation'] is True
